/**
 * Messages, cut 10 (photos saved on arrival): our copy of each picture or file that comes on a text. Quo hands the
 * webhook a link to it, and "Quo's link to the picture is best treated as temporary" (the prototype's
 * `quo-messages-mockup.html` draft 8, on branch spike/gc-mode), so the app keeps its own copy the moment the text
 * arrives, in the private message-attachments bucket an email's files use (cut 6), on `message_attachments` rows. One that
 * did not copy keeps a row all the same, marked `quo_not_copied`: the line still says a picture came, and Quo's own
 * history still holds it.
 */
import { KEEP_FILE_BYTES } from '../emailIn/emailLine.ts'
import { fileKindOf } from '../documents/jobFiles.ts'
import { extOf } from '../photos/photoName.ts'
import type { QuoMedia } from './events.ts'

/** The mark on a text's picture or file the webhook could not copy (`message_attachments.left_in_gmail`). */
export const QUO_NOT_COPIED = 'quo_not_copied'

/** What the webhook fetches for one of a text's files, and where its copy goes. */
export interface QuoMediaPlan {
  /** Its place among the line's files, from 0. */
  sort_order: number
  /** Quo's link, fetched once on arrival. */
  url: string
  /** *picture-1.jpg*, *file-2.pdf*: a text's files come with no names. */
  name: string
  mime: string | null
  /** quo/<the text's Quo id>/<place>.<ending> in message-attachments. */
  bucket_path: string
}

/** How the fetch went: the bytes it read, or none. */
export type QuoMediaFetch = { ok: true; bytes: number } | { ok: false; bytes?: number | null }

/** The row for one of a text's files, as `message_attachments` takes it. */
export interface QuoMediaRow {
  message_id: string
  sort_order: number
  kind: 'file'
  name: string
  mime: string | null
  size_bytes: number | null
  bucket_path: string | null
  left_in_gmail: typeof QUO_NOT_COPIED | null
}

/** A Quo id as a folder name in the bucket: letters, digits, dashes and underscores only. */
function pathSafe(id: string): string {
  return id.replace(/[^A-Za-z0-9_-]/g, '_').slice(0, 120) || 'text'
}

/** What to fetch for each of a text's files, in the order Quo sent them. */
export function quoMediaPlans(quoId: string, media: readonly QuoMedia[]): QuoMediaPlan[] {
  return media.map((m, i) => {
    const place = i + 1
    const ext = extOf(m.type)
    const word = fileKindOf(m.type ?? '') === 'image' ? 'picture' : 'file'
    const name = ext ? `${word}-${place}.${ext}` : `${word}-${place}`
    return { sort_order: i, url: m.url, name, mime: m.type, bucket_path: `quo/${pathSafe(quoId)}/${ext ? `${place}.${ext}` : place}` }
  })
}

/**
 * The files still to keep for a line: Quo sends a delivery again when the webhook answered 500, so a file the line already
 * has a row for, by its place, is left alone and nothing is kept twice.
 */
export function mediaToKeep(plans: readonly QuoMediaPlan[], keptOrders: Iterable<number>): QuoMediaPlan[] {
  const kept = new Set(keptOrders)
  return plans.filter((p) => !kept.has(p.sort_order))
}

/** Whether a fetch gives us a copy to keep: it read, and it fits the cap an email's files have. */
export function keepsCopy(fetched: QuoMediaFetch): boolean {
  return fetched.ok && fetched.bytes <= KEEP_FILE_BYTES
}

/** The row to write once the fetch is done: our copy when it read and fits the cap an email's files have, else the mark. */
export function quoMediaRow(messageId: string, plan: QuoMediaPlan, fetched: QuoMediaFetch): QuoMediaRow {
  const bytes = fetched.bytes ?? null
  const kept = keepsCopy(fetched)
  return {
    message_id: messageId,
    sort_order: plan.sort_order,
    kind: 'file',
    name: plan.name,
    mime: plan.mime,
    size_bytes: bytes,
    bucket_path: kept ? plan.bucket_path : null,
    left_in_gmail: kept ? null : QUO_NOT_COPIED,
  }
}
